.news-form input::placeholder { color: var(--text-mute); }
.news-form input:focus {
  border-color: var(--accent);
  background: var(--surface-2);
}
.news-status {
  flex-basis: 100%;
  min-height: 1.2em;
  font-size: 0.85rem;
  margin-top: 4px;
  padding-left: 4px;
}
.news-status.is-success { color: var(--success); }
.news-status.is-error { color: var(--danger); }

/* FOOTER */
.site-footer {
  background: var(--bg-2);
  border-top: 1px solid var(--line);
  padding-top: 60px;
  color: var(--text-dim);
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 40px;
  padding-bottom: 50px;
}
.foot-brand p {
  margin-top: 14px;
  font-size: 0.9rem;
  max-width: 320px;
}
.foot-brand .brand-mark { font-size: 1rem; }
.foot-brand .brand-name {
  font-family: 'Fraunces', Georgia, serif;
  font-size: 1.2rem;
  color: var(--text);
}
.site-footer h2 {
  font-family: 'Inter', sans-serif;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--text);
  margin-bottom: 16px;
  font-weight: 600;
}
.site-footer nav ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.site-footer nav a {
  font-size: 0.9rem;
  color: var(--text-dim);
}
.site-footer nav a:hover { color: var(--accent-2); }

.foot-base {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-block: 24px;
  border-top: 1px solid var(--line);
  font-size: 0.82rem;
  color: var(--text-mute);
  flex-wrap: wrap;
  gap: 12px;
}
.foot-legal {
  display: flex;
  gap: 22px;
  list-style: none;
  margin: 0; padding: 0;
}

/* RESPONSIVE */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto auto;
  }
  .deal-feature { grid-column: span 2; grid-row: auto; }
  .editorial-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto auto;
  }
  .story-lead { grid-column: span 2; grid-row: auto; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 820px) {
  .header-inner {
    grid-template-columns: auto 1fr;
    gap: 16px;
  }
  .primary-nav { display: none; }
  .search input { width: 140px; }
  .hero-inner { grid-template-columns: 1fr; gap: 40px; }
  .hero-visual { max-width: 480px; margin-inline: auto; width: 100%; }
  .news-inner { grid-template-columns: 1fr; gap: 28px; }
  .hero { padding: 56px 0 70px; }
  .featured, .deals, .editorial { padding: 60px 0; }
}

@media (max-width: 600px) {
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .story-lead { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .hero-meta { grid-template-columns: 1fr 1fr; gap: 20px; }
  .search { padding-left: 10px; }
  .search input { width: 110px; }
  .section-head { flex-direction: column; align-items: flex-start; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

