}
.deal-art-b {
  background:
    linear-gradient(160deg, #1d2230 0%, #0f1219 100%);
}
.deal-art-c {
  background:
    linear-gradient(135deg, #221a14 0%, #100c08 100%);
}
.deal-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 20%, rgba(212,180,131,0.28), transparent 55%);
