}

.deal-body {
  padding: 22px 22px 26px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.deal-body h3 {
  font-size: 1.25rem;
  margin: 0;
}
.deal-body p {
  color: var(--text-dim);
  font-size: 0.92rem;
}
.deal-kicker {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--accent);
  font-weight: 600;
}
