.story-art-1 {
  background:
    linear-gradient(135deg, #2c2218 0%, #14110c 70%),
    radial-gradient(circle at 70% 30%, rgba(212,180,131,0.4), transparent 60%);
  background-blend-mode: overlay;
}
.story-art-2 {
  background:
    linear-gradient(160deg, #1c2535 0%, #0d1019 70%),
