  background-blend-mode: screen;
}
.story-art-3 {
  background:
    linear-gradient(135deg, #2a2520 0%, #161310 70%),
    radial-gradient(circle at 60% 50%, rgba(212,180,131,0.35), transparent 55%);
  background-blend-mode: overlay;
}
.story-art-4 {
  background:
